export interface BridgeScriptOptions {
  /** Where Runova writes its port and token. Read on every call, since the port changes per launch. */
  portFile: string;
  projectId: string;
}

/**
 * The script Claude Code starts for this project. It has no dependencies, so it runs with whatever
 * `node` the project already uses for its hooks. It writes only protocol messages to stdout.
 */
export function bridgeScriptSource({ portFile, projectId }: BridgeScriptOptions): string {
  return String.raw`#!/usr/bin/env node
// Generated by Runova. Lets the AI agent in this project list the project's run commands and
// suggest new ones. A suggestion waits for approval in Runova, so nothing is saved or run
// without the user agreeing. Regenerated whenever "Let agents suggest run commands" changes.
'use strict';

const fs = require('node:fs');
const http = require('node:http');
const readline = require('node:readline');

const PORT_FILE = ${JSON.stringify(portFile)};
const PROJECT_ID = ${JSON.stringify(projectId)};
const DEFAULT_PROTOCOL_VERSION = '2025-06-18';

const TOOLS = [
  {
    name: 'list_run_commands',
    description:
      'List the run commands Runova has for this project. Each one has a label and the command it runs.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
  },
  {
    name: 'propose_run_command',
    description:
      'Suggest a run command for this project, such as a dev server or an app on an emulator. The user sees the suggestion in Runova and must approve it before it is saved. Nothing runs until the user approves it and presses Run. The command is typed into the terminal as written, in this project folder.',
    inputSchema: {
      type: 'object',
      properties: {
        label: {
          type: 'string',
          description: 'A short name for the environment, for example "android dev". Optional.',
        },
        command: {
          type: 'string',
          description: 'One line of shell text for the terminal the project uses (PowerShell on Windows).',
        },
      },
      required: ['command'],
      additionalProperties: false,
    },
  },
];

function send(message) {
  process.stdout.write(JSON.stringify(message) + '\n');
}

function textResult(text, isError) {
  return { content: [{ type: 'text', text: text }], isError: Boolean(isError) };
}

function readConnection() {
  try {
    const data = JSON.parse(fs.readFileSync(PORT_FILE, 'utf-8'));
    if (typeof data.port === 'number' && typeof data.token === 'string') return data;
  } catch {
    // No file yet, or Runova has never run here: the caller reports it as not running.
  }
  return null;
}

/** One request to Runova. Rejects with a message the agent can show to the user. */
function askRunova(body) {
  return new Promise((resolve, reject) => {
    const connection = readConnection();
    if (!connection) {
      reject(new Error('Runova is not running.'));
      return;
    }
    const payload = JSON.stringify({ ...body, token: connection.token, projectId: PROJECT_ID });
    const request = http.request(
      {
        host: '127.0.0.1',
        port: connection.port,
        path: '/run-commands',
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'content-length': Buffer.byteLength(payload),
        },
        timeout: 5000,
      },
      (response) => {
        let data = '';
        response.setEncoding('utf-8');
        response.on('data', (chunk) => {
          data += chunk;
        });
        response.on('end', () => {
          try {
            resolve(JSON.parse(data));
          } catch {
            reject(new Error('Runova sent an answer this bridge cannot read.'));
          }
        });
      },
    );
    request.on('timeout', () => request.destroy(new Error('Runova did not answer in time.')));
    request.on('error', (error) =>
      reject(new Error(error.code === 'ECONNREFUSED' ? 'Runova is not running.' : error.message)),
    );
    request.end(payload);
  });
}

async function callTool(name, args) {
  const input = args && typeof args === 'object' ? args : {};
  if (name === 'list_run_commands') {
    const answer = await askRunova({ action: 'list' });
    if (!answer.ok) return textResult(answer.error || 'Runova could not list the run commands.', true);
    return textResult(JSON.stringify(answer.commands, null, 2), false);
  }
  if (name === 'propose_run_command') {
    const answer = await askRunova({
      action: 'propose',
      label: typeof input.label === 'string' ? input.label : '',
      command: typeof input.command === 'string' ? input.command : '',
    });
    if (!answer.ok) return textResult(answer.error || 'Runova did not accept the suggestion.', true);
    return textResult(answer.message, false);
  }
  return null;
}

async function handle(message) {
  if (!message || typeof message !== 'object') return;
  // Notifications such as notifications/initialized carry no id and get no answer.
  if (message.id === undefined || message.id === null) return;
  const id = message.id;
  const params = message.params || {};

  if (message.method === 'initialize') {
    const version =
      typeof params.protocolVersion === 'string' ? params.protocolVersion : DEFAULT_PROTOCOL_VERSION;
    send({
      jsonrpc: '2.0',
      id,
      result: {
        protocolVersion: version,
        capabilities: { tools: {} },
        serverInfo: { name: 'runova', version: '1.0.0' },
      },
    });
    return;
  }
  if (message.method === 'ping') {
    send({ jsonrpc: '2.0', id, result: {} });
    return;
  }
  if (message.method === 'tools/list') {
    send({ jsonrpc: '2.0', id, result: { tools: TOOLS } });
    return;
  }
  if (message.method === 'tools/call') {
    let result;
    try {
      result = await callTool(params.name, params.arguments);
    } catch (error) {
      result = textResult(error instanceof Error ? error.message : 'Something went wrong.', true);
    }
    if (result === null) {
      send({ jsonrpc: '2.0', id, error: { code: -32602, message: 'Unknown tool: ' + String(params.name) } });
      return;
    }
    send({ jsonrpc: '2.0', id, result });
    return;
  }
  send({ jsonrpc: '2.0', id, error: { code: -32601, message: 'Method not found: ' + String(message.method) } });
}

// Requests still waiting on Runova when stdin closes must be answered before the process exits.
let inFlight = 0;
let inputClosed = false;

function exitWhenIdle() {
  if (inputClosed && inFlight === 0) process.exit(0);
}

const lines = readline.createInterface({ input: process.stdin, terminal: false });
lines.on('line', (line) => {
  if (line.trim() === '') return;
  let message;
  try {
    message = JSON.parse(line);
  } catch {
    send({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'Parse error' } });
    return;
  }
  inFlight += 1;
  handle(message)
    .catch(() => {})
    .finally(() => {
      inFlight -= 1;
      exitWhenIdle();
    });
});
lines.on('close', () => {
  inputClosed = true;
  exitWhenIdle();
});
`;
}
